// The moves the regulation has, as their pages show them: generated by `npm run gen-data` (`moves.data.json`), typed
// here.

import DATA from '@/data/generated/moves.data.json'
import type { MoveId, PokemonId } from '@/data/dex'
import type { TypeId } from '@/data/types'

export const CATEGORIES = ['physical', 'special', 'status'] as const
export type Category = (typeof CATEGORIES)[number]

/** Showdown's move flags the app shows (`MOVE_FLAGS` in `scripts/gen-data.ts`). */
export const FLAGS = [
  'contact',
  'sound',
  'punch',
  'bite',
  'slicing',
  'pulse',
  'sheerforce',
  'bullet',
  'wind',
  'powder',
  'dance',
  'heal',
  'gravity',
  'bypasssub',
  'reflectable',
  'protect',
  'charge',
  'cantusetwice',
] as const
export type Flag = (typeof FLAGS)[number]

/** Whom a move hits, as Showdown names it. */
export const TARGETS = [
  'normal',
  'any',
  'randomNormal',
  'allAdjacentFoes',
  'allAdjacent',
  'adjacentAlly',
  'adjacentAllyOrSelf',
  'self',
  'allies',
  'allySide',
  'allyTeam',
  'foeSide',
  'all',
  'scripted',
] as const
export type Target = (typeof TARGETS)[number]

export interface Move {
  type: TypeId
  category: Category
  /** 0 for status moves, and for moves whose power varies (their text says how). */
  power: number
  /** `true` for moves that never miss. */
  accuracy: number | true
  /** As Champions has it, PP Ups included. */
  pp: number
  priority: number
  target: Target
  /** `protect` means it goes through Protect. */
  flags: Flag[]
  /** The Pokémon that learn it, one per species, when they're 3 at most (`FEW_LEARNERS` in `scripts/gen-data.ts`). */
  learners?: PokemonId[]
  /** One of the series' signature moves: only one evolutionary family learns it, in any game (`scripts/signatures.ts`). */
  signature?: true
}

export const MOVES = DATA as unknown as Record<MoveId, Move>

/**
 * A move's tag for how few learn it (`MoveTag`): Signature, one of the series' signature moves, else Exclusive, when only
 * one Pokémon learns it in the regulation; each with the Pokémon it's of (a signature move's first learner here).
 */
export interface MoveTag {
  kind: 'signature' | 'exclusive'
  of?: PokemonId
}
export const moveTag = (m: Move): MoveTag | undefined =>
  m.signature
    ? { kind: 'signature', of: m.learners?.[0] }
    : m.learners?.length === 1
      ? { kind: 'exclusive', of: m.learners[0] }
      : undefined

/**
 * Whom a move reaches, in short, for the move rankings: Showdown's targets grouped by what they mean in a double
 * battle (its full target, `move.target.*`, says exactly whom).
 */
export const REACHES = ['one', 'foes', 'around', 'self', 'ally', 'side', 'foeSide', 'field'] as const
export type Reach = (typeof REACHES)[number]
const REACH: Record<Target, Reach> = {
  normal: 'one',
  any: 'one',
  randomNormal: 'one',
  scripted: 'one',
  allAdjacentFoes: 'foes',
  allAdjacent: 'around',
  self: 'self',
  adjacentAlly: 'ally',
  adjacentAllyOrSelf: 'ally',
  allies: 'side',
  allySide: 'side',
  allyTeam: 'side',
  foeSide: 'foeSide',
  all: 'field',
}
export const reachOf = (m: Move): Reach => REACH[m.target]

/** A move's priority as shown, when it has one: "+4", "−7" (a minus sign); null at 0. */
export const priorityLabel = (m: Move) =>
  m.priority > 0 ? `+${m.priority}` : m.priority < 0 ? `−${-m.priority}` : null

/**
 * A move's priority as a filter (`searchTerms.ts`): raised or lowered at all, or each value a move the regulation has
 * runs at, the highest first (`p1` is +1, `m3` −3).
 */
export const PRIORITIES = [
  'up',
  'down',
  ...[...new Set(Object.values(MOVES).map((m) => m.priority))]
    .filter((p) => p)
    .sort((a, b) => b - a)
    .map((p) => (p > 0 ? `p${p}` : `m${-p}`)),
]
export type Priority = string
const priorityValue = (id: Priority) => (id[0] === 'p' ? 1 : -1) * Number(id.slice(1))
/** Whether a move has the priority a filter stands for. */
export const hasPriority = (m: Move, id: Priority) =>
  id === 'up' ? m.priority > 0 : id === 'down' ? m.priority < 0 : m.priority === priorityValue(id)
/** A priority filter's ID for a move's priority, when it has one: what its badge leads to. */
export const priorityId = (m: Move): Priority | null =>
  m.priority > 0 ? `p${m.priority}` : m.priority < 0 ? `m${-m.priority}` : null
/** A priority filter's label: "+1", "−3" (a minus sign). */
export const priorityIdLabel = (id: Priority) => {
  const v = priorityValue(id)
  return v > 0 ? `+${v}` : `−${-v}`
}

/** Moves that hit more than one Pokémon: their damage is reduced to 0.75× when they do. */
export const isSpread = (m: Move) => m.target === 'allAdjacentFoes' || m.target === 'allAdjacent'
